// The extra builds of every class (buildGuides.variants.*.data.js, generated by scripts/build-guides): the same
// checks the main guides get, plus what only makes sense for several builds of one class -- they must really
// differ, be reachable in the window, and keep the English and Ukrainian copies in step.
import { describe, it, expect, afterEach } from 'vitest';
import { BUILD_GUIDES } from '../buildGuides.data.js';
import { BUILD_GUIDE_VARIANTS } from '../buildGuides.variants.data.js';
import { BUILD_GUIDE_VARIANTS_UK } from '../buildGuides.variants.uk.data.js';
import { getBuildGuide, getBuildGuides, MAIN_BUILD_ID, loadBuildVariant, saveBuildVariant, variantStorageKey } from '../buildGuide.js';
import { getSkillById } from '../skillsData.js';
import { setLang } from '../../i18n/i18n.js';

const CLASSES = ['Warrior', 'Mage', 'Monk', 'Cultist', 'Archer', 'Druid'];
const STATS = ['STR', 'DEX', 'CON', 'INT', 'WIS', 'CHA'];
const KINDS = ['minor', 'notable', 'greater', 'keystone'];
const START = { Warrior: 'start-strength', Mage: 'start-intelligence', Monk: 'start-wisdom', Cultist: 'start-constitution', Archer: 'start-dexterity', Druid: 'start-charisma' };
const nonEmpty = (s) => typeof s === 'string' && s.trim().length > 0;

describe('the extra builds', () => {
  it('give every class exactly two more builds, with ids that cannot collide', () => {
    expect(Object.keys(BUILD_GUIDE_VARIANTS)).toEqual(CLASSES);
    const ids = [];
    for (const c of CLASSES) {
      expect(BUILD_GUIDE_VARIANTS[c]).toHaveLength(2);
      for (const g of BUILD_GUIDE_VARIANTS[c]) ids.push(g.id);
    }
    expect(new Set(ids).size).toBe(ids.length);
    expect(ids).not.toContain(MAIN_BUILD_ID);
  });

  describe.each(CLASSES.flatMap((c) => BUILD_GUIDE_VARIANTS[c].map((g) => [g.id, c, g])))('%s', (id, cls, g) => {
    it('has identity and text fields', () => {
      expect(g.className).toBe(cls);
      expect(g.id).toMatch(/^[a-z]+_[a-z]+$/);
      for (const k of ['name', 'summary', 'playstyle']) expect(nonEmpty(g[k])).toBe(true);
    });

    it('has 3-5 stat priorities with valid codes', () => {
      expect(g.stats.length).toBeGreaterThanOrEqual(3);
      expect(g.stats.length).toBeLessThanOrEqual(5);
      for (const s of g.stats) { expect(STATS).toContain(s.stat); expect(nonEmpty(s.why)).toBe(true); }
    });

    it('has a 9-slot hotbar of real, distinct skills of this class', () => {
      expect(g.hotbar).toHaveLength(9);
      expect(g.hotbar.map((h) => h.slot)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      expect(new Set(g.hotbar.map((h) => h.skillId)).size).toBe(9);
      for (const h of g.hotbar) {
        const skill = getSkillById(h.skillId);
        expect(skill, `${id} hotbar skill ${h.skillId}`).toBeTruthy();
        expect(skill.class).toBe(cls);
        expect(h.name).toBe(skill.nameEn);
        expect(nonEmpty(h.unlock)).toBe(true);
        expect(nonEmpty(h.why)).toBe(true);
      }
    });

    it('has early skills that exist, at the level the catalog says', () => {
      expect(g.earlySkills.length).toBeGreaterThan(0);
      for (const e of g.earlySkills) {
        const skill = getSkillById(e.skillId);
        expect(skill, `${id} early skill ${e.skillId}`).toBeTruthy();
        expect(skill.class).toBe(cls);
        expect(e.name).toBe(skill.nameEn);
        expect(e.level).toBe(skill.reqLvl);
        expect(nonEmpty(e.note)).toBe(true);
      }
    });

    it('has a 150-step route of unique keys starting from the class\'s own start node', () => {
      const p = g.passives;
      expect(p.startKey).toBe(START[cls]);
      expect(p.steps).toHaveLength(150);
      const keys = p.steps.map((s) => s.key);
      expect(new Set(keys).size).toBe(150);
      expect(keys).not.toContain(p.startKey);
      for (const s of p.steps) { expect(nonEmpty(s.key)).toBe(true); expect(nonEmpty(s.label)).toBe(true); expect(KINDS).toContain(s.kind); }
    });

    it('has the five milestones and key nodes that point at the right step', () => {
      expect(g.passives.milestones.map((m) => m.points)).toEqual([10, 30, 60, 100, 150]);
      for (const m of g.passives.milestones) expect(nonEmpty(m.summary)).toBe(true);
      const { keystones, steps } = g.passives;
      expect(keystones.length).toBeGreaterThan(0);
      let prev = 0;
      for (const k of keystones) {
        expect(steps[k.atStep - 1].key).toBe(k.key);
        expect(steps[k.atStep - 1].label).toBe(k.label);
        expect(nonEmpty(k.note)).toBe(true);
        expect(k.atStep).toBeGreaterThan(prev);
        prev = k.atStep;
      }
    });

    it('has gear and weakness bullets and leaves no placeholder behind', () => {
      for (const list of [g.gear, g.weaknesses]) {
        expect(list.length).toBeGreaterThan(0);
        for (const line of list) expect(nonEmpty(line)).toBe(true);
      }
      expect(JSON.stringify(g)).not.toMatch(/\{[a-z0-9_]+\}/);
    });
  });

  it('are really different builds: no two of a class share a hotbar or a route', () => {
    for (const c of CLASSES) {
      const all = [BUILD_GUIDES[c], ...BUILD_GUIDE_VARIANTS[c]];
      for (let i = 0; i < all.length; i += 1) {
        for (let j = i + 1; j < all.length; j += 1) {
          const a = new Set(all[i].hotbar.map((h) => h.skillId));
          const shared = all[j].hotbar.filter((h) => a.has(h.skillId)).length;
          expect(shared, `${c}: builds ${i} and ${j} share ${shared} of 9 hotbar skills`).toBeLessThanOrEqual(5);
          const ra = all[i].passives.steps.map((s) => s.key);
          const rb = new Set(all[j].passives.steps.map((s) => s.key));
          const overlap = ra.filter((k) => rb.has(k)).length;
          expect(overlap, `${c}: routes ${i} and ${j} share ${overlap} of 150 nodes`).toBeLessThan(145);
          expect(all[i].name).not.toBe(all[j].name);
        }
      }
    }
  });

  it('the Druid has the wolf-only and the human-caster builds the design asks for', () => {
    const [wolf, moon] = BUILD_GUIDE_VARIANTS.Druid;
    const ids = (g) => g.hotbar.map((h) => h.skillId);
    // Wolf Pack: a wolf form and wolf skills plus buffs, no spells that would be cast at a penalty in the form.
    expect(ids(wolf)).toContain('dru_wolf_form');
    expect(ids(wolf)).not.toContain('dru_hawk_form');
    expect(ids(wolf)).not.toContain('dru_bear_form');
    for (const id of ids(wolf)) expect(getSkillById(id).type).not.toBe('magic');
    // Moon Caster: no forms at all.
    for (const id of ids(moon)) expect(id).not.toMatch(/_form$/);
    expect(ids(moon).filter((id) => getSkillById(id).type === 'magic').length).toBeGreaterThanOrEqual(4);
  });
});

describe('the extra builds in Ukrainian', () => {
  const TEXT_FIELDS = ['name', 'summary', 'playstyle'];
  it('mirror the English ones: same classes, ids, skills, nodes and shape', () => {
    expect(Object.keys(BUILD_GUIDE_VARIANTS_UK)).toEqual(Object.keys(BUILD_GUIDE_VARIANTS));
    for (const c of CLASSES) {
      expect(BUILD_GUIDE_VARIANTS_UK[c].map((g) => g.id)).toEqual(BUILD_GUIDE_VARIANTS[c].map((g) => g.id));
      BUILD_GUIDE_VARIANTS[c].forEach((en, i) => {
        const uk = BUILD_GUIDE_VARIANTS_UK[c][i];
        expect(Object.keys(uk).sort()).toEqual(Object.keys(en).sort());
        expect(uk.hotbar.map((h) => [h.slot, h.skillId])).toEqual(en.hotbar.map((h) => [h.slot, h.skillId]));
        expect(uk.earlySkills.map((e) => [e.skillId, e.level])).toEqual(en.earlySkills.map((e) => [e.skillId, e.level]));
        expect(uk.passives.steps.map((s) => [s.key, s.kind])).toEqual(en.passives.steps.map((s) => [s.key, s.kind]));
        expect(uk.passives.keystones.map((k) => [k.key, k.atStep])).toEqual(en.passives.keystones.map((k) => [k.key, k.atStep]));
        expect(uk.passives.milestones.map((m) => m.points)).toEqual(en.passives.milestones.map((m) => m.points));
        expect(uk.stats.map((s) => s.stat)).toEqual(en.stats.map((s) => s.stat));
        expect(uk.gear).toHaveLength(en.gear.length);
        expect(uk.weaknesses).toHaveLength(en.weaknesses.length);
      });
    }
  });

  it('really translate the text, and use the Ukrainian skill names', () => {
    for (const c of CLASSES) {
      BUILD_GUIDE_VARIANTS[c].forEach((en, i) => {
        const uk = BUILD_GUIDE_VARIANTS_UK[c][i];
        for (const k of TEXT_FIELDS) expect(uk[k], `${en.id}.${k}`).not.toBe(en[k]);
        uk.gear.forEach((s, n) => expect(s).not.toBe(en.gear[n]));
        uk.weaknesses.forEach((s, n) => expect(s).not.toBe(en.weaknesses[n]));
        uk.hotbar.forEach((h) => expect(h.name).toBe(getSkillById(h.skillId).nameUk));
        expect(JSON.stringify(uk)).not.toMatch(/\{[a-z0-9_]+\}/);
      });
    }
  });
});

describe('the freshness rules the main guides obey', () => {
  const EN_CD = /(\d+(?:\.\d+)?) s cooldown/;
  const UK_CD = /перезарядк[а-я]* (\d+(?:\.\d+)?) с/;
  const EN_COST = /(\d+)( (?:mana|stamina))(?! per tick)/;
  const UK_COST = /(\d+)( (?:мани|витривалості))(?! за такт)/;
  const STALE = [/not implemented/i, /не реалізован/i, /Costs 0 mana/i, /Безкоштовн/i, /at (?:no|zero) cost/i, /wastes mana/i];
  const SETS = [['en', BUILD_GUIDE_VARIANTS, EN_CD, EN_COST], ['uk', BUILD_GUIDE_VARIANTS_UK, UK_CD, UK_COST]];

  it.each(SETS)('%s: quoted cooldowns and costs match the catalog, and no stale notes', (_l, set, cd, cost) => {
    const bad = [];
    for (const list of Object.values(set)) {
      for (const g of list) {
        for (const h of g.hotbar) {
          const s = getSkillById(h.skillId);
          const m1 = cd.exec(h.why);
          if (m1 && Number(m1[1]) !== s.cooldown) bad.push(`${g.id}/${h.skillId}: cooldown ${m1[1]} vs ${s.cooldown}`);
          const m2 = cost.exec(h.why);
          if (m2 && !s.costPct && !s.channeled && s.cost > 0 && Number(m2[1]) !== s.cost) bad.push(`${g.id}/${h.skillId}: cost ${m2[1]} vs ${s.cost}`);
        }
        const scan = JSON.stringify(g);
        for (const re of STALE) if (re.test(scan)) bad.push(`${g.id}: stale phrase ${re}`);
      }
    }
    expect(bad).toEqual([]);
  });
});

describe('picking a build', () => {
  afterEach(() => setLang('en'));

  it('lists the main build first, then the extra ones', () => {
    const list = getBuildGuides('Druid');
    expect(list.map((b) => b.id)).toEqual([MAIN_BUILD_ID, 'druid_wolf', 'druid_moon']);
    expect(list[0].guide).toBe(BUILD_GUIDES.Druid);
    expect(getBuildGuides('druid')).toHaveLength(3);                     // case-insensitive, like the main lookup
    expect(getBuildGuides('Paladin')).toEqual([]);
    expect(getBuildGuides(null)).toEqual([]);
  });

  it('getBuildGuide returns the chosen build, and the main one for no or an unknown id', () => {
    expect(getBuildGuide('Druid')).toBe(BUILD_GUIDES.Druid);
    expect(getBuildGuide('Druid', undefined, 'druid_wolf').id).toBe('druid_wolf');
    expect(getBuildGuide('Druid', undefined, MAIN_BUILD_ID)).toBe(BUILD_GUIDES.Druid);
    expect(getBuildGuide('Druid', undefined, 'no_such_build')).toBe(BUILD_GUIDES.Druid);
    expect(getBuildGuide('Mage', undefined, 'druid_wolf')).toBe(BUILD_GUIDES.Mage);   // another class's id cannot leak in
  });

  it('an explicit guides argument means exactly those guides: no extra builds are mixed in', () => {
    const custom = { Druid: { className: 'Druid' } };
    expect(getBuildGuides('Druid', custom).map((b) => b.id)).toEqual([MAIN_BUILD_ID]);
    expect(getBuildGuide('Druid', custom, 'druid_wolf')).toBe(custom.Druid);
  });

  it('follows the interface language, with the same ids', () => {
    setLang('uk');
    const uk = getBuildGuides('Warrior');
    expect(uk.map((b) => b.id)).toEqual([MAIN_BUILD_ID, 'warrior_bulwark', 'warrior_executioner']);
    expect(uk[1].guide).toBe(BUILD_GUIDE_VARIANTS_UK.Warrior[0]);
    expect(getBuildGuide('Warrior', undefined, 'warrior_executioner').name).toBe(BUILD_GUIDE_VARIANTS_UK.Warrior[1].name);
  });

  it('remembers the choice per character', () => {
    const m = new Map();
    const storage = { getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => m.set(k, String(v)), removeItem: (k) => m.delete(k) };
    expect(loadBuildVariant(7, storage)).toBe(MAIN_BUILD_ID);
    saveBuildVariant(7, 'druid_moon', storage);
    expect(loadBuildVariant(7, storage)).toBe('druid_moon');
    expect(loadBuildVariant(8, storage)).toBe(MAIN_BUILD_ID);
    expect(m.has(variantStorageKey(7))).toBe(true);
    saveBuildVariant(7, MAIN_BUILD_ID, storage);                          // back to main stores nothing
    expect(m.has(variantStorageKey(7))).toBe(false);
  });

  it('a blocked or missing storage never throws', () => {
    const boom = { getItem() { throw new Error('blocked'); }, setItem() { throw new Error('blocked'); }, removeItem() { throw new Error('blocked'); } };
    expect(loadBuildVariant(1, boom)).toBe(MAIN_BUILD_ID);
    expect(() => saveBuildVariant(1, 'x', boom)).not.toThrow();
    expect(loadBuildVariant(1, null)).toBe(MAIN_BUILD_ID);
  });
});
